edits.replacement:
reg __rtlrefine_ack_delay=0;
initial o_wb_ack=0;
always @(posedge i_clk) begin
 if (!i_wb_cyc) begin __rtlrefine_ack_delay<=0; o_wb_ack<=0; end
 else begin __rtlrefine_ack_delay<=wb_stb; o_wb_ack<=__rtlrefine_ack_delay; end
end

